body.page-auth-backoffice {
--ink: #0a2324;
  --ink-soft: #0a2324;
  --ink-deep: #0a2324;
  --ink-rgb: 10, 35, 36;
  --text-ink: #0a2324;
  --ink-banner: linear-gradient(135deg, #0a2324 0%, #0a2324 58%, #0a2324 100%);
  color: var(--text-ink);
  background:
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.68), transparent 18%),
    linear-gradient(180deg, #f7f2ec 0%, #f1ebe5 100%);
}

body.page-auth-backoffice :where(
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  p,
  li,
  dt,
  dd,
  label,
  legend,
  blockquote,
  figcaption
) {
color: var(--text-ink);
}

.app-nav-inner-backend {
max-width: 1400px;
}

body.page-auth-backoffice .backend-shell {
max-width: 1080px;
  padding: 1.35rem 1rem 3rem;
}

body.page-auth-backoffice .backend-topbar {
grid-template-columns: minmax(0, 1fr);
}

body.page-auth-backoffice .editor-panel.backend-panel {
box-shadow: 0 10px 28px rgba(17, 17, 17, 0.08);
}

body.page-auth-backoffice .auth-site-access {
background:
  linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 247, 244, 0.96)),
  linear-gradient(135deg, rgba(45, 190, 183, 0.1), rgba(17, 17, 17, 0.025));
}

body.page-auth-backoffice .auth-site-links {
display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

body.page-auth-backoffice .auth-site-link {
justify-content: center;
  min-width: min(100%, 13.5rem);
}

body.page-auth-backoffice h1,
body.page-auth-backoffice h2,
body.page-auth-backoffice h3,
body.page-auth-backoffice .eyebrow,
body.page-auth-backoffice .button {
font-family: "Oswald", "Arial Narrow", sans-serif;
  letter-spacing: 0.04em;
}

body:has(.app-nav-inner-backend) .app-nav {
border-bottom: 1px solid rgba(8, 9, 9, 0.08);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 0.6rem 1.8rem rgba(8, 9, 9, 0.06);
  backdrop-filter: blur(14px);
}

body:has(.app-nav-inner-backend) .app-nav-inner-backend {
max-width: 1480px;
  padding: 0.55rem clamp(0.9rem, 2.2vw, 1.8rem);
  gap: clamp(0.7rem, 1.2vw, 1.2rem);
}

body:has(.app-nav-inner-backend) .brand-wordmark-poster {
display: inline-grid;
