color: #050505;
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: clamp(1rem, 1.5vw, 1.22rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.9;
  text-transform: uppercase;
}

body:has(.app-nav-inner-backend) .brand-wordmark-poster .brand-wordmark-city-initial,
body:has(.app-nav-inner-backend) .brand-wordmark-poster .brand-wordmark-live {
font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: clamp(1rem, 1.5vw, 1.22rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.9;
  text-transform: uppercase;
}

body:has(.app-nav-inner-backend) .brand-wordmark-poster .brand-wordmark-city-initial {
color: #050505;
}

body:has(.app-nav-inner-backend) .brand-wordmark-poster .brand-wordmark-live {
color: #050505;
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated {
margin-left: auto;
  padding-left: 0;
  gap: 0.38rem;
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated::before {
display: none;
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link,
body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-form .app-nav-link {
min-height: 2.25rem;
  padding: 0 0.78rem;
  border: 1px solid rgba(8, 9, 9, 0.1);
  border-radius: 999px;
  background: rgba(245, 244, 241, 0.72);
  color: #0a2324;
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: 0.82rem;
  font-weight: 400;
  letter-spacing: 0;
  line-height: 1;
  text-transform: uppercase;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.7);
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link:hover,
body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-form .app-nav-link:hover {
border-color: rgba(8, 9, 9, 0.2);
  background: #fff;
  color: #0a2324;
  transform: translateY(-1px);
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link::after,
body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-form .app-nav-link::after {
display: none;
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link:hover::after,
body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-form .app-nav-link:hover::after {
display: none;
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-active,
body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-form .app-nav-link.app-nav-link-active {
border-color: #050505;
  background: #050505;
  color: #fff;
}

body:has(.app-nav-inner-backend) .app-nav-links-group-separated .app-nav-link-active::after {
display: none;
}

body:has(.app-nav-inner-backend) .app-nav-toggle {
border: 1px solid rgba(8, 9, 9, 0.1);
  border-radius: 999px;
  background: rgba(245, 244, 241, 0.78);
  color: #050505;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.82);
  backdrop-filter: none;
}

body:has(.app-nav-inner-backend) .app-nav-toggle:hover,
body:has(.app-nav-inner-backend) .app-nav-toggle:focus-visible {
border-color: rgba(8, 9, 9, 0.18);
  background: #fff;
  transform: translateY(-1px);
}

