<!DOCTYPE html>
<html lang="<%= I18n.locale %>">
  <head>
    <title><%= content_for(:title) || "Stuttgart Live" %></title>
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="application-name" content="Stuttgart Live">
    <meta name="mobile-web-app-capable" content="yes">
    <% backend_context = controller_path.start_with?("backend/") %>
    <% auth_chrome = controller_path == "sessions" ||
                     (controller_path == "passwords" && action_name == "new") %>
    <% frontend_context = controller_path.start_with?("public/") || controller_path == "errors" %>
    <% if controller_path.start_with?("backend/") %>
      <meta name="turbo-cache-control" content="no-cache">
    <% end %>
    <%= csrf_meta_tags %>
    <%= csp_meta_tag %>
    <% unless controller_path.start_with?("backend/") %>
      <script>
        try {
          if (window.localStorage && window.localStorage.getItem("stuttgart-live-consent-v1")) {
            document.documentElement.classList.add("consent-preference-stored")
          }
        } catch (_) {}
      </script>
      <style>
        html.consent-preference-stored .consent-banner {
          display: none;
        }
      </style>
    <% end %>

    <%= yield :head %>

    <link rel="icon" href="/icon.svg" type="image/svg+xml">
    <link rel="alternate icon" href="/icon.png" type="image/png">
    <link rel="apple-touch-icon" href="/icon.png">

    <% if asset_available?("archivo-narrow-400.woff2") %>
      <link rel="preload" href="<%= asset_path("archivo-narrow-400.woff2") %>" as="font" type="font/woff2" crossorigin>
    <% end %>
    <% if asset_available?("oswald-700.woff2") %>
      <link rel="preload" href="<%= asset_path("oswald-700.woff2") %>" as="font" type="font/woff2" crossorigin>
    <% end %>
    <% if asset_available?("oswald-300.ttf") %>
      <link rel="preload" href="<%= asset_path("oswald-300.ttf") %>" as="font" type="font/ttf" crossorigin>
    <% end %>
    <% if frontend_context || backend_context || auth_chrome %>
      <style data-local-font-faces>
        <%= local_font_face_stylesheet(frontend: frontend_context) %>
      </style>
    <% end %>
    <% if compiled_asset_exists?("shared.css") %>
      <%= stylesheet_link_tag "shared", "data-turbo-track": "reload" %>
    <% end %>
    <% css_asset = backend_context || auth_chrome ? "backend" : (frontend_context ? "frontend" : nil) %>
    <% if css_asset.present? && compiled_asset_exists?("#{css_asset}.css") %>
      <%= stylesheet_link_tag css_asset, "data-turbo-track": "reload" %>
    <% end %>
    <% javascript_asset = controller_path.start_with?("backend/") ? "backend" : "public" %>
    <% if compiled_asset_exists?("#{javascript_asset}.js") %>
      <%= javascript_include_tag javascript_asset, "data-turbo-track": "reload", type: "module" %>
    <% end %>
    <% if defined?(::Sentry) && ::Sentry.respond_to?(:get_trace_propagation_meta) %>
      <%= ::Sentry.get_trace_propagation_meta.to_s.html_safe %>
    <% end %>
  </head>

  <% public_frontend = controller_path.start_with?("public/") || controller_path == "errors" %>
  <% public_homepage_chrome = controller_path.start_with?("public/") || controller_path == "errors" %>
  <% public_design_preview = (controller_path == "public/events" && action_name.in?(%w[design_preview design_preview_detail])) ||
                             (controller_path == "public/pages" && action_name == "design_preview_service") %>
  <% public_startpage = controller_path == "public/events" && action_name == "index" %>
