  <% body_classes << "page-public-newsletter-poster" if public_frontend %>
  <% body_classes << "page-public-events-index" if public_homepage_chrome %>
  <% body_classes << "page-public-startpage" if public_startpage %>
  <% body_classes << "page-public-detail" if public_frontend && action_name == "show" %>
  <% body_classes << "page-public-design-preview" if public_modern_design %>
  <% header_color_variants = [
       { key: "black", label: "1", name: "Dunkelgrau" },
