@import "tailwindcss";
@import "./actiontext.css";

:root {
--ink: #111111;
  --ink-soft: #2a2a2a;
  --ink-deep: #050505;
  --ink-rgb: 17, 17, 17;
  --ink-banner: linear-gradient(135deg, #111111 0%, #202020 100%);
  --paper: #ffffff;
  --paper-dark: #d9d9d9;
  --accent: #e31b2e;
  --accent-dark: #b91122;
  --line: #c6c6c6;
}

body {
margin: 0;
  color: var(--ink);
  background: var(--paper);
  font-family: "Archivo Narrow", "Arial Narrow", sans-serif;
}

html {
scroll-behavior: smooth;
}

.sr-only {
position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
position: absolute;
  left: 1rem;
  top: 0.75rem;
  z-index: 120;
  padding: 0.65rem 0.9rem;
  background: var(--ink);
  color: #fff;
  font-weight: 700;
  text-decoration: none;
  transform: translateY(-140%);
  transition: transform 140ms ease;
}

.skip-link:focus-visible {
transform: translateY(0);
}

input,
textarea,
select,
button {
font: inherit;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:not([tabindex="-1"]):focus-visible {
outline: 3px solid var(--accent);
  outline-offset: 3px;
}

a {
color: inherit;
}

.app-nav {
position: sticky;
  top: 0;
  z-index: 30;
  border-bottom: 1px solid var(--line);
  background:
    linear-gradient(120deg, rgba(231, 92, 88, 0.34) 0%, rgba(240, 154, 70, 0.3) 24%, rgba(244, 216, 96, 0.28) 46%, rgba(129, 183, 231, 0.24) 72%, rgba(156, 208, 165, 0.28) 100%);
  backdrop-filter: blur(8px);
}

.app-nav-inner {
max-width: 1220px;
  margin: 0 auto;
  padding: 0.85rem 1rem;
  display: flex;
  gap: 0.75rem;
  align-items: center;
  position: relative;
}

.app-brand {
display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  text-decoration: none;
}

.app-brand-with-tagline {
align-items: flex-start;
  flex-direction: column;
  gap: 0;
  padding-bottom: 1.42rem;
  position: relative;
}

.app-nav-search {
flex: 1 1 24rem;
  min-width: 16rem;
  max-width: 28rem;
  transform: translateY(2px);
}

.brand-wordmark {
display: inline-flex;
  align-items: baseline;
  color: #000;
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: clamp(1.55rem, 3.4vw, 2.3rem);
  line-height: 1;
  white-space: nowrap;
  transition: transform 160ms ease, opacity 160ms ease;
}

.brand-wordmark-city {
font-weight: 200;
  letter-spacing: 0.08em;
}

.brand-wordmark-live {
font-weight: 700;
  letter-spacing: 0.01em;
}

.brand-tagline {
color: rgba(0, 0, 0, 0.72);
  display: block;
  height: 0.78rem;
  left: 0;
