body.page-public {
--ink: #0a2324;
  --ink-soft: #0a2324;
  --ink-deep: #0a2324;
  --ink-rgb: 10, 35, 36;
  --public-accent: #2bd7cf;
  --public-accent-strong: #00c5cc;
  --public-accent-soft: #59e8de;
  --public-accent-rgb: 43 215 207;
  --accent: var(--public-accent);
  --public-gray-header-background:
    radial-gradient(circle at 70% 24%, rgba(255, 255, 255, 0.28), transparent 18%),
    radial-gradient(circle at 52% 10%, rgba(255, 255, 255, 0.16), transparent 24%),
    linear-gradient(105deg, #1b1c1c 0%, #383a3a 36%, #949898 66%, #555858 100%);
  --public-gray-header-glow-background:
    linear-gradient(
      112deg,
      transparent 28%,
      rgba(255, 255, 255, 0.02) 40%,
      rgba(255, 255, 255, 0.38) 52%,
      rgba(255, 255, 255, 0.08) 62%,
      transparent 72%
    );
  --text-ink: #0a2324;
  --event-price-color: #0a2324;
  --ink-banner: linear-gradient(135deg, #0a2324 0%, #0a2324 58%, #0a2324 100%);
  color: var(--text-ink);
  overflow-x: hidden;
  overflow-x: clip;
}

body.page-public :where(
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  p,
  li,
  dt,
  dd,
  label,
  legend,
  blockquote,
  figcaption
) {
color: var(--text-ink);
}

.public-backend-float {
position: fixed;
  top: var(--app-nav-height, 0px);
  right: max(
    var(--homepage-content-padding-inline, 1rem),
    calc(((100vw - var(--homepage-content-max-width, 1480px)) / 2) + var(--homepage-content-padding-inline, 1rem))
  );
  left: auto;
  z-index: 40;
  width: max-content;
  max-width: calc(100vw - 2rem);
  pointer-events: none;
