    linear-gradient(135deg, rgba(227, 27, 46, 0.04), rgba(17, 17, 17, 0.02));
}

.backend-topbar {
display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  align-items: end;
  gap: 0.75rem;
  margin-bottom: 0.9rem;
}

.backend-topbar-title {
display: flex;
  flex-wrap: nowrap;
  align-items: baseline;
  gap: 0.5rem 0.8rem;
  min-width: 0;
  overflow: hidden;
}

.backend-topbar-sticky {
position: sticky;
  top: var(--app-nav-height, 0px);
  z-index: 20;
  padding: 0.2rem 0 0.4rem;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(255, 255, 255, 0.94) 82%, rgba(255, 255, 255, 0) 100%);
  backdrop-filter: blur(10px);
}

.backend-topbar h1 {
margin: 0.05rem 0 0;
  line-height: 0.9;
  text-transform: uppercase;
  font-size: clamp(1.45rem, 3.2vw, 2.5rem);
  white-space: nowrap;
  flex: 0 0 auto;
}

.backend-topbar-actions {
display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.backend-topbar-controls {
display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
  margin-top: 0.2rem;
}

.backend-topbar-editor-actions:empty {
display: none;
}

.backend-inbox-control-rail {
display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  min-width: 0;
}

.backend-inbox-control-rail > * {
min-width: 0;
}

.backend-status-row {
display: flex;
  flex-wrap: nowrap;
  gap: 0.5rem;
  overflow-x: auto;
  margin-right: 0;
  padding-right: 0;
  padding-bottom: 0.4rem;
  margin-bottom: 0.9rem;
}

.status-chip {
display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.55rem;
  border: 1px solid var(--line);
  background: #fff;
  text-decoration: none;
  text-transform: uppercase;
  font-size: 0.82rem;
}

.status-chip-active {
border-color: #121212;
  background: #121212;
  color: #fff;
}

.backend-split {
display: grid;
  gap: 1rem;
  grid-template-columns: 1fr;
}

.backend-list-column,
.backend-editor-column {
border: 1px solid var(--line);
  background: #fff;
  padding: 0.75rem;
}

.backend-list-column {
display: flex;
  flex-direction: column;
}

.filter-form {
border: 1px solid #ececec;
  padding: 0.6rem;
  margin-bottom: 0.6rem;
}
  font-size: 0.7rem;
  line-height: 1;
}

.editor-panel,
.backend-panel {
display: grid;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid rgba(17, 17, 17, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(247, 244, 241, 0.98)),
