#blog_editor_panel.editor-panel.backend-panel {
border: 0;
}

#page_editor_panel.editor-panel.backend-panel,
#presenter_editor_panel.editor-panel.backend-panel,
#venue_editor_panel.editor-panel.backend-panel {
border: 0;
}

#backend_account_password_panel.editor-panel.backend-panel {
margin-bottom: 1rem;
}

.press-checkbox-block {
display: grid;
  gap: 0.45rem;
}

.form-input,
.form-textarea {
width: 100%;
  border: 1px solid #d0d0d0;
  background: #fcfcfc;
  padding: 0.43rem 0.48rem;
  font-size: 1rem;
  text-transform: none;
}

.form-input {
font-family: "Archivo Narrow", "Arial Narrow", sans-serif;
}

.form-textarea {
font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-size: 0.94rem;
  line-height: 1.15;
}

.form-input:focus,
.form-textarea:focus {
border-color: #666;
}

.form-input:focus-visible,
.form-textarea:focus-visible {
outline: 3px solid #b8b8b8;
