item.stdout:
.design-detail-preview-panel.design-detail-preview-media {
  margin-top: clamp(2.2rem, 4vw, 3.6rem);
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.design-detail-preview-media .design-detail-preview-panel-label {
  margin-bottom: 0.45rem;
}

.design-detail-preview-media .consent-media-card,
.design-detail-preview-media .video-frame,
.design-detail-preview-local-video {
  width: 100%;
}

.design-detail-preview-media .consent-media-placeholder {
  min-height: clamp(18rem, 46vw, 34rem);
  align-content: center;
  border-radius: 0.52rem;
  background:
    linear-gradient(135deg, rgba(8, 9, 9, 0.82), rgba(8, 9, 9, 0.5)),
    linear-gradient(45deg, rgba(255, 255, 255, 0.12), transparent);
  color: #fff;
}

.design-detail-preview-media .consent-media-placeholder h3,
.design-detail-preview-media .consent-media-placeholder p {
  max-width: 42rem;
  color: inherit;
}

.design-detail-preview-media .consent-media-actions .button {
  border-color: rgba(255, 255, 255, 0.68);
  color: #fff;
}

.design-detail-preview-media .video-frame {
  margin-top: 0;
  border-radius: 0.42rem;
}

.design-detail-preview-local-video {

.consent-banner {
position: fixed;
  right: 1rem;
  bottom: 1rem;
  z-index: 60;
  width: min(36rem, calc(100vw - 2rem));
  display: grid;
  gap: 1rem;
  border: 1px solid rgba(17, 17, 17, 0.16);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(247, 244, 238, 0.98)),
    linear-gradient(135deg, rgba(227, 27, 46, 0.07), rgba(240, 154, 70, 0.08));
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.16);
  padding: 1rem;
}

.consent-banner h2,
.consent-dialog h2,
.consent-media-placeholder h3 {
margin: 0;
  text-transform: uppercase;
}

.consent-banner p,
.consent-option p,
.consent-media-placeholder p {
margin: 0;
  line-height: 1.45;
}

.consent-banner-copy {
display: grid;
  gap: 0.45rem;
}

.consent-banner-actions,
.consent-dialog-actions,
.consent-media-actions {
display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.consent-banner-actions .button,
.consent-dialog-actions .button {
display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.15rem;
  padding-block: 0.6rem 0.5rem;
  text-indent: 0.08em;
}

<% if presenter.youtube_embed_url.present? %>
  <section class="event-detail-panel event-detail-video">
    <%= render "shared/consent_video_embed",
               title: "#{presenter.meta_title} auf YouTube",
               url: presenter.youtube_embed_url %>
  </section>
<% end %>
Port 3000: geschlossen
Port 8400: geschlossen

