.design-detail-preview-flow {
  display: grid;
  gap: 0.85rem;
  color: var(--preview-ink);
  font-size: 0.9rem;
  font-weight: 300;
  line-height: 1.5rem;
  text-wrap: pretty;
}

.design-detail-preview-flow :where(p, ul, ol, h2, h3, h4) {
  margin: 0;
}

.design-detail-preview-flow .attachment--preview .attachment__caption {
  display: none;
}

.design-detail-preview-flow :where(h2, h3, h4) {
  color: var(--preview-ink);
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-weight: 400;
  line-height: 1;
}

.design-detail-preview-flow h2 {
  font-size: clamp(1.8rem, 2.9vw, 2.3rem);
}

.design-detail-preview-flow h3 {
  font-size: clamp(1.45rem, 2.25vw, 1.78rem);
}

.design-detail-preview-flow h4 {
  font-size: clamp(1.15rem, 1.65vw, 1.35rem);
}

.design-detail-preview-flow p {
  max-width: 68ch;
}

.design-detail-preview-flow p + p {
  margin-top: 0.2rem;
}

.design-detail-preview-flow--long {
  position: relative;
  display: block;
  padding-left: 0.95rem;
}

.design-detail-preview-flow--long::before {
  content: "";
  position: absolute;
  top: 0.18rem;
  bottom: 0.18rem;
  left: 0;
  width: 2px;
  border-radius: 999px;
  background: rgba(8, 9, 9, 0.12);
}

.design-detail-preview-flow--long :where(p, ul, ol) {
  margin-bottom: 0.82rem;
}

.design-detail-preview-flow--long :where(p, ul, ol):last-child {
  margin-bottom: 0;
}

.design-detail-preview-flow :where(ul, ol),
.design-detail-preview-notes ul {
  display: grid;
  gap: 0.45rem;
    min-height: calc(64.2rem - 2.5rem);
  }

  .design-detail-preview-description-toggle,
  .design-detail-preview-related .design-preview-card-row {
    align-content: start;
  }

  .design-detail-preview-flow {
    font-size: 0.9rem;
  }

  .design-detail-preview-side--desktop-inline .design-detail-preview-panel {
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  .design-detail-preview-side--desktop-inline .design-detail-preview-location {
    margin-top: 0;
    padding-top: 0;
    border-top: 0;
  }

  .design-detail-preview-side--desktop-inline .design-detail-preview-vvs {
    top: auto;
    right: 0;
    bottom: 0;
  }

  .design-detail-preview-side--desktop-inline .design-detail-preview-notes {
    align-self: start;
    padding-top: 1.15rem;
    border-top: 1px solid rgba(8, 9, 9, 0.09);
  }

  .design-detail-preview-flow--long {
    display: grid;
    gap: 0.85rem;
    padding-left: 0;
  }

  .design-detail-preview-flow--long::before {
    display: none;
  }

  .design-detail-preview-flow--long :where(p, ul, ol, h3) {
    max-width: none;
    break-inside: avoid;
  }

  .design-detail-preview-related {
    align-self: start;
    margin-top: 0;
  }
}

