async (page) => {
 const results=[];
 for (const width of [390,820,1440]) {
  const touch=width<1000;
  const context=await page.context().browser().newContext({viewport:{width,height:960},isMobile:width===390,hasTouch:touch});
  const p=await context.newPage();
  const measure=async(selector,pseudo=null)=>p.locator(selector).first().evaluate((e,pseudo)=>{
   const c=getComputedStyle(e,pseudo),r=e.getBoundingClientRect();
   const rgb=s=>(s.match(/[\d.]+/g)||[]).map(Number);
   const over=(a,b)=>a.slice(0,3).map((v,i)=>v*(a[3]??1)+b[i]*(1-(a[3]??1)));
   let bg=[255,255,255]; const parents=[]; for(let q=e;q;q=q.parentElement)parents.unshift(q);
   for(const q of parents)bg=over(rgb(getComputedStyle(q).backgroundColor),bg);
   const fg=over(rgb(c.color),bg);
   const lum=x=>x.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((s,v,i)=>s+v*[.2126,.7152,.0722][i],0);
   const a=lum(fg),b=lum(bg),contrast=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);
   return{width:r.width,height:r.height,fontSize:c.fontSize,lineHeight:c.lineHeight,color:c.color,background:c.backgroundColor,contrast,outline:c.outline,text:e.textContent.trim().slice(0,100)};
  },pseudo);
  await p.goto('http://127.0.0.1:3001/rock-alternative');
  await p.evaluate(()=>document.fonts.ready);
  const list={};
  for(const selector of ['.design-preview-card-date','.design-preview-card-location','.design-preview-card-price--body','.design-preview-list-card-grid .saved-event-button'])list[selector]=await measure(selector);
  await p.locator('.design-preview-list-card-grid .saved-event-button').first().click();
  await p.locator('.design-preview-saved-link').click();
  const remove=p.locator('.design-preview-saved-remove').first(); await remove.waitFor();
  const saved=await measure('.design-preview-saved-remove');
  const separated=await remove.evaluate(e=>{const a=e.getBoundingClientRect(),b=e.parentElement.querySelector('a').getBoundingClientRect();return a.right<=b.left||b.right<=a.left||a.bottom<=b.top||b.bottom<=a.top});
  await p.screenshot({path:'/tmp/stuttgart-task2-after-saved-'+width+'.png'});
  const beforeURL=p.url(); await remove.click({position:{x:3,y:3}});
  const removed=await p.locator('.design-preview-saved-remove').count()===0;
  const stayed=p.url()===beforeURL;
  await p.goto('http://127.0.0.1:3001/events/the-kilkennys-2026-10-21');
  await p.evaluate(()=>document.fonts.ready);
  const detail={};
  for(const selector of ['.design-detail-preview-flow--long','.consent-media-actions .button-secondary','.design-preview-footer-nav-group h2'])detail[selector]=await measure(selector);
  detail.placeholder=await measure('.design-preview-footer-newsletter-form input[type="email"]','::placeholder');
  const button=p.locator('.consent-media-actions .button-secondary').first(); await button.scrollIntoViewIfNeeded();
  await p.screenshot({path:'/tmp/stuttgart-task2-after-media-'+width+'.png'});
  await button.hover(); detail.youtubeHover=await measure('.consent-media-actions .button-secondary');
  await button.focus(); detail.youtubeFocus=await measure('.consent-media-actions .button-secondary');
  await p.locator('.design-detail-preview-flow--long').scrollIntoViewIfNeeded();
  await p.screenshot({path:'/tmp/stuttgart-task2-after-copy-'+width+'.png'});
  const overflow=await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
  results.push({width,touch,list,saved,separated,removed,stayed,detail,overflow});
  await context.close();
 }
 return results;
}

