async (page) => {
 const results=[];
 for (const width of [320,390,820,1440]) {
  const context=await page.context().browser().newContext({viewport:{width,height:844},isMobile:width<=390,hasTouch:width<=820});
  const p=await context.newPage();
  await p.goto('http://127.0.0.1:3001/events/the-kilkennys-2026-10-21');
  const consent=p.getByRole('button',{name:'Nur notwendige',exact:true});if(await consent.isVisible())await consent.click();
  await p.evaluate(()=>document.fonts.ready);
  const data=await p.locator('a.event-detail-cta-button').evaluate(e=>{
   const n=document.getElementById(e.getAttribute('aria-describedby')),bar=e.closest('.design-detail-preview-actions');
   const rect=x=>{const r=x.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom}};
   return{href:e.href,target:e.target,description:n?.textContent.trim(),descriptionId:e.getAttribute('aria-describedby'),noteRect:n?rect(n):null,linkRect:rect(e),bar:rect(bar),barPosition:getComputedStyle(bar).position,overflow:document.documentElement.scrollWidth>innerWidth};
  });
  await p.screenshot({path:'/tmp/stuttgart-task3-top-'+width+'.png'});
  await p.evaluate(()=>scrollTo(0,document.documentElement.scrollHeight));
  const bottom=await p.evaluate(()=>{const bar=document.querySelector('.design-detail-preview-actions'),r=bar.getBoundingClientRect();return{viewportHeight:innerHeight,barTop:r.top,barBottom:r.bottom,overflow:document.documentElement.scrollWidth>innerWidth}});
  await p.screenshot({path:'/tmp/stuttgart-task3-bottom-'+width+'.png'});
  results.push({width,...data,bottom});
  await context.close();
 }
 return results;
}

