}

.design-detail-preview-related .design-preview-card-media {
  width: 5.25rem;
  min-width: 5.25rem;
  height: 5.25rem;
  min-height: 5.25rem;
  aspect-ratio: 1 / 1;
  border-radius: 0.38rem;
}

.design-detail-preview-related .design-preview-card-copy,
.design-detail-preview-related .design-preview-card--has-actions .design-preview-card-copy {
  gap: 0.13rem;
  min-height: 4.7rem;
  padding: 0.1rem 0.08rem 1.55rem;
}

.design-detail-preview-related .design-preview-card-kicker,
.design-detail-preview-related .design-preview-card-subtitle,
.design-detail-preview-related .design-preview-card-price,
.design-detail-preview-related .design-preview-card-series-pill {
  display: none;
}

.design-detail-preview-related .design-preview-card-title {
  display: -webkit-box;
  overflow: hidden;
  font-size: clamp(0.78rem, 2.6vw, 0.95rem);
  line-height: 1.08;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  text-transform: none;
}

.design-detail-preview-related .design-preview-card-meta {
  font-size: 0.62rem;
  line-height: 1.12;
}

.design-detail-preview-related .design-preview-card-date-location-row {
  display: grid;
  gap: 0.06rem;
}

.design-detail-preview-related .design-preview-card-location {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.design-detail-preview-related .design-preview-card-actions {
  top: calc(5.25rem - var(--preview-card-control-size) - 0.18rem);
  right: auto;
  bottom: auto;
  left: 0.02rem;
  width: auto;
  gap: 0;
}

.design-detail-preview-related .saved-event-button.design-preview-card-save {
  width: var(--preview-card-control-size);
  height: var(--preview-card-control-size);
}

.design-detail-preview-related .saved-event-button.design-preview-card-save .saved-event-button-icon {
  width: 0.7rem;
  height: 0.7rem;
}
  .design-detail-preview-links a > span:not(.design-detail-preview-link-icon) {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
  }

  .design-detail-preview-link-icon,
