  .design-preview-list-card-grid .design-preview-card-date-location-row .design-preview-card-location,
  .design-detail-preview-related .design-preview-card-date-location-row .design-preview-card-location,
  .design-service-preview-highlights .design-preview-card-date-location-row .design-preview-card-location {
    flex: 1 1 auto;
    width: auto;
    min-width: 0;
  }

  .design-detail-preview-related .design-preview-card-meta,
  .design-detail-preview-related .design-preview-card-date,
  .design-detail-preview-related .design-preview-card-location {
    font-size: 0.84rem;
    line-height: 1.18;
  }
}


.saved-events-page-title {
